// src/jsx/CreateGroup.jsx
import { useState } from "react";
import { db } from "../js/firebaseConfig";
import { collection, addDoc, serverTimestamp } from "firebase/firestore";
import useSearchUsers from "../hooks/useSearchUsers";

export default function CreateGroup({ currentUser, setScreen }) {

    const [name, setName] = useState("");

    // Hook de busca
    const { filtered, search, searchUsers } = useSearchUsers();

    // Membros selecionados
    const [selected, setSelected] = useState([]);

    const toggle = (id) => {
        setSelected(prev =>
            prev.includes(id)
                ? prev.filter(x => x !== id)
                : [...prev, id]
        );
    };

    const create = async () => {
        if (!name) return alert("Nome do grupo obrigatório");
        if (selected.length === 0) return alert("Selecione pelo menos 1 membro");

        await addDoc(collection(db, "groups"), {
            name,
            members: [currentUser.uid, ...selected],
            createdAt: serverTimestamp()
        });

        setScreen("private");
    };

    // Remove o usuário atual da lista
    const usersToShow = filtered.filter(u => u.id !== currentUser.uid);

    return (
        <div>
            <h2>Criar Grupo</h2>

            <input
                placeholder="Nome do grupo"
                value={name}
                onChange={e => setName(e.target.value)}
            />

            <input
                placeholder="Pesquisar usuários"
                value={search}
                onChange={e => searchUsers(e.target.value)}
            />

            <h3>Membros</h3>
            {usersToShow.map(u => (
                <label key={u.id}>
                    <input
                        type="checkbox"
                        checked={selected.includes(u.id)}
                        onChange={() => toggle(u.id)}
                    />
                    {u.email}
                </label>
            ))}

            <button onClick={create}>Criar</button>
            <button onClick={() => setScreen("private")}>Cancelar</button>
        </div>
    );
}
